    return q
ACTS=['mvU','mvD','mvL','mvR','shrink','six','tele','grow']+['shrinkAt%d'%i for i in range(4)]+['growAt%d'%i for i in range(4)]
COST={'mv':1,'shrink':5,'six':4,'tele':4,'grow':5,'shrinkAt':5,'growAt':5}
